INSERT INTO `comments` (`id`, `video_id`, `comment_id`, `author`, `text`, `likes`, `published_at`, `is_reply`, `parent_comment_id`, `created_at`) VALUES
(2996, 'Vo2rSYsO90s', 'Vo2rSYsO90s_915', '@MamasKaryokali-zby', 'Program sensus untuk alasan proyek negara biar bisa ngucurin dana dan bisa di korup, 😂\nRakyat gak butuh sensus, rakyat butuhnya perbaikan ekonomi,😂', 0, '2026-07-17 17:15:11', 0, NULL, '2026-07-23 08:36:47'),
(2997, 'Vo2rSYsO90s', 'Vo2rSYsO90s_916', '@ariftm5742', 'Alah mau sensusnya sukses data di input real. Lalu dengan tujuan untuk memetakan anggaran pembangunan, tetapi program yang di beri anggaran selalu di korupsi ketika pelaksanaan untuk apa masyarakat sudah terlalu sakit hati jangan harap masyarakat mau di jadikan sapi perah untuk memperkaya pejabat2 nol prestasi nol hasil terapi keluarganya semakin hari semakin kaya. Apa2 mahal cari kerja susah. Masyarakat tetap di mintain pajak. Mereka ini petugas sensus kerja 2/5 bulan di gaji -+ 10 JT. Katanya efesisnsi anggaran semua proyek negara menelan sangat jumbo anggaran.', 0, '2026-07-17 09:08:42', 0, NULL, '2026-07-23 08:36:47'),
